const V={};
const listViz=items=>root=>{root.innerHTML=`<div class="vl">${items.map(it=>`<div class="li"><b>${it[0]}</b><span>${it[1]}</span></div>`).join('')}</div>`;const els=[...root.querySelectorAll('.li')];return{tick(t,dt,P,vs){els.forEach((e,i)=>{e.classList.toggle('on',P(i+1)>.5);e.classList.toggle('act',vs===i+1)})}}};

