V.convex=root=>{const s=mount(root,640,320),m1=Mp(-2,2,-.3,4.3,30,300,30,280),m2=Mp(-2.2,2.2,-1.3,2.3,340,610,30,280),f=x=>x*x,g=x=>.25*x**4-x*x+.2*x+.6;
s.innerHTML=`<g class="p1"><polyline points="${pts(f,-2,2,m1)}" class="cv"/><line class="c1" stroke="var(--green)" stroke-width="4"/><circle class="a1" r="6" fill="var(--green)"/><circle class="b1" r="6" fill="var(--green)"/><text x="165" y="306" text-anchor="middle" font-size="18" style="fill:var(--green)">convexa: un solo valle</text></g>
<g class="p2"><polyline points="${pts(g,-2.2,2.2,m2)}" class="cv"/><line class="c2" stroke="var(--red)" stroke-width="4"/><text x="475" y="306" text-anchor="middle" font-size="18" style="fill:var(--red)">no convexa: varios valles</text></g><text class="l3" x="320" y="22" text-anchor="middle" font-size="18" style="fill:var(--mut)">f(tx + (1−t)y) ≤ t f(x) + (1−t) f(y)   (Jensen)</text>`;
const q=c=>s.querySelector(c);return{tick(t,dt,P){const a=-1.6+.3*Math.sin(t),b=1.3+.4*Math.cos(t*.7);at(q('.c1'),{x1:m1.X(a),y1:m1.Y(f(a)),x2:m1.X(b),y2:m1.Y(f(b))});at(q('.a1'),{cx:m1.X(a),cy:m1.Y(f(a))});at(q('.b1'),{cx:m1.X(b),cy:m1.Y(f(b))});const c=-1.5+.2*Math.sin(t*.8),d=1.5+.2*Math.cos(t);at(q('.c2'),{x1:m2.X(c),y1:m2.Y(g(c)),x2:m2.X(d),y2:m2.Y(g(d))});op(q('.p1'),P(1)?1:.25);op(q('.p2'),.15+.85*P(2));op(q('.l3'),P(3))}}};
V.tsp=root=>{const C=[[60,210],[150,90],[210,250],[270,140],[340,290],[410,100],[480,230],[570,150]],d=(a,b)=>Math.hypot(C[a][0]-C[b][0],C[a][1]-C[b][1]),len=t=>t.reduce((S,c,i)=>S+d(c,t[(i+1)%t.length]),0);let cur=0;const nn=[0];while(nn.length<8){let b=-1,bd=1e9;for(let j=0;j<8;j++)if(!nn.includes(j)&&d(cur,j)<bd){bd=d(cur,j);b=j}nn.push(b);cur=b}
let best=1e9,bt=[];const perm=(a,l)=>{if(!a.length){const tt=[0,...l],Lq=len(tt);if(Lq<best){best=Lq;bt=tt}return}a.forEach((x,i)=>perm(a.filter((_,k)=>k!==i),[...l,x]))};perm([1,2,3,4,5,6,7],[]);const path=t=>t.map(i=>C[i].join(',')).join(' ')+' '+C[t[0]].join(',');
const s=mount(root,640,340,`<polyline class="nn" points="${path(nn)}" fill="none" stroke="var(--amber)" stroke-width="4" stroke-dasharray="10 7"/><polyline class="op" points="${path(bt)}" fill="none" stroke="var(--teal)" stroke-width="5"/>${C.map((c,i)=>`<circle cx="${c[0]}" cy="${c[1]}" r="${i?9:12}" fill="${i?'var(--ink)':'var(--acc)'}"/>`).join('')}<text x="${C[0][0]-10}" y="${C[0][1]+34}" font-size="16" style="fill:var(--acc)">inicio</text><text class="t1" x="20" y="30" font-size="19" style="fill:var(--amber)">más cercano: ${fmt(len(nn)/10,1)} km</text><text class="t2" x="20" y="56" font-size="19" style="fill:var(--teal)">óptimo: ${fmt(best/10,1)} km</text>`);
const q=c=>s.querySelector(c);return{tick(t,dt,P){op(q('.nn'),P(2));op(q('.t1'),P(2));op(q('.op'),P(3));op(q('.t2'),P(3))}}};
