const F1=x=>2+Math.sin(1.3*x)+.6*Math.sin(3.1*x)+.15*x;
V.ga=root=>{const m=Mp(0,10,0,5,40,600,30,290);const s=mount(root,640,330,`<polyline points="${pts(F1,0,10,m)}" class="cv"/><g class="pop"></g><text class="gen" x="40" y="24" font-size="19"></text><text class="lb" x="600" y="320" text-anchor="end" font-size="17" style="fill:var(--mut)">selección · cruce · mutación</text>`);
const q=c=>s.querySelector(c),N=14,g=q('.pop');for(let i=0;i<N;i++)g.insertAdjacentHTML('beforeend',`<circle r="8" fill="var(--acc)" stroke="var(--dial)" stroke-width="2"/>`);const cs=[...g.children];let pop,gen,acc=0;const reset=()=>{seed=11;pop=Array.from({length:N},()=>rnd()*2.5);gen=0};reset();
return{tick(t,dt,P){if(P(2)>.5&&!SNAP){acc+=dt;if(acc>.8){acc=0;gen++;pop.sort((a,b)=>F1(b)-F1(a));const best=pop.slice(0,7),sig=Math.max(.15,1.4*Math.pow(.85,gen));const kids=[];for(let i=0;i<N-7;i++){const a=best[Math.floor(rnd()*7)],b=best[Math.floor(rnd()*7)];kids.push(clamp((a+b)/2+gauss()*sig,0,10))}pop=[...best,...kids];if(gen>22)reset()}}cs.forEach((c,i)=>at(c,{cx:m.X(pop[i]),cy:m.Y(F1(pop[i]))-9}));q('.gen').textContent=`generación ${gen}`;op(g,P(1));op(q('.lb'),P(3))}}};
const G1=x=>1.1*Math.sin(2.3*x)+.7*Math.sin(5.1*x)+.06*(x-6.5)**2;
V.anneal=root=>{const m=Mp(0,10,-2.2,4.2,40,600,30,290);let gx=0,gb=1e9;for(let x=0;x<=10;x+=.005)if(G1(x)<gb){gb=G1(x);gx=x}
const s=mount(root,640,330,`<polyline points="${pts(G1,0,10,m,300)}" class="cv"/><circle cx="${m.X(gx)}" cy="${m.Y(gb)+18}" r="5" fill="var(--green)"/><text x="${m.X(gx)}" y="${m.Y(gb)+42}" text-anchor="middle" font-size="15" style="fill:var(--green)">global</text><circle class="w" r="11" fill="var(--acc)"/><g class="tb"><rect x="40" y="10" width="200" height="14" rx="7" fill="var(--soft)" stroke="var(--line)"/><rect class="tf" x="40" y="10" height="14" rx="7" fill="var(--red)"/><text x="250" y="23" font-size="16">temperatura</text></g>`);
const q=c=>s.querySelector(c);let x=1,T=2.5,acc=0;return{tick(t,dt,P){if(P(1)>.5&&!SNAP){acc+=dt;while(acc>.09){acc-=.09;const y=clamp(x+gauss()*(.25+.5*T),0,10),dE=G1(y)-G1(x);if(dE<0||Math.random()<Math.exp(-dE/T))x=y;T*=.985;if(T<.02){T=2.5;x=1+Math.random()*1.5}}}at(q('.w'),{cx:m.X(x),cy:m.Y(G1(x))-11});at(q('.tf'),{width:200*Math.min(1,T/2.5)});op(q('.tb'),P(1)?(.35+.65*P(3)):0)}}};
const F2=(x,y)=>((x-1.2)**2+(y+.8)**2)/8-Math.cos(2*(x-1.2))*Math.cos(2*(y+.8));
function Swarm(s,m,n=18){const g=document.createElementNS('http://www.w3.org/2000/svg','g');s.appendChild(g);for(let i=0;i<n;i++)g.insertAdjacentHTML('beforeend',`<circle r="6" fill="#FFC94A" stroke="#2B1E3A" stroke-width="2"/>`);g.insertAdjacentHTML('beforeend',`<path class="gb" d="M0 -12 L3.5 -3.5 12 -3 5 2.5 7.5 11 0 6 -7.5 11 -5 2.5 -12 -3 -3.5 -3.5Z" fill="var(--acc)" stroke="#fff" stroke-width="1.5"/>`);const cs=[...g.querySelectorAll('circle')];let p,acc=0,age=0;
const reset=()=>{p=Array.from({length:n},()=>{const x=-4+8*Math.random(),y=-3+6*Math.random();return{x,y,vx:0,vy:0,bx:x,by:y,bf:F2(x,y)}});age=0};reset();
return{g,step(dt){acc+=dt;age+=dt;if(age>9)reset();while(acc>.12){acc-=.12;let gb=p.reduce((a,b)=>b.bf<a.bf?b:a);p.forEach(q=>{q.vx=.6*q.vx+1.3*Math.random()*(q.bx-q.x)+1.3*Math.random()*(gb.bx-q.x);q.vy=.6*q.vy+1.3*Math.random()*(q.by-q.y)+1.3*Math.random()*(gb.by-q.y);q.x=clamp(q.x+q.vx,-4,4);q.y=clamp(q.y+q.vy,-3,3);const f=F2(q.x,q.y);if(f<q.bf){q.bf=f;q.bx=q.x;q.by=q.y}})}},draw(){const gb=p.reduce((a,b)=>b.bf<a.bf?b:a);cs.forEach((c,i)=>at(c,{cx:m.X(p[i].x),cy:m.Y(p[i].y)}));g.querySelector('.gb').setAttribute('transform',`translate(${m.X(gb.bx)} ${m.Y(gb.by)})`)}}}
V.swarm=root=>{const m=Mp(-4,4,-3,3,40,600,20,300),img=heat(F2,-4,4,-3,3);const s=mount(root,640,330,`<image href="${img}" x="40" y="20" width="560" height="280" preserveAspectRatio="none"/><text x="40" y="322" font-size="16" style="fill:var(--mut)">oscuro = valor bajo (mínimo) · estrella = mejor global del enjambre</text>`);const sw=Swarm(s,m);
return{tick(t,dt,P){if(P(1)>.5&&!SNAP)sw.step(dt);sw.draw();op(sw.g,P(1)?1:.0)}}};
