V.form=root=>{root.innerHTML=`<div class="fx"><div>minimizar  fᵢ(x),  i = 1, 2, …, M<small>funciones objetivo (coste o energía); M = 1: un solo objetivo</small></div><div>sujeto a  φⱼ(x) = 0,  j = 1, …, J<small>restricciones de igualdad</small></div><div>          ψₖ(x) ≤ 0,  k = 1, …, K<small>restricciones de desigualdad</small></div><div>x = (x₁, x₂, …, xₙ)ᵀ<small>vector de diseño: variables de decisión continuas, discretas o mixtas</small></div></div>`;const els=[...root.querySelectorAll('.fx div')];return{tick(t,dt,P,vs){els.forEach((e,i)=>{e.classList.toggle('on',P(i+1)>.5);e.classList.toggle('act',vs===i+1)})}}};
V.spaces=root=>{const s=mount(root,640,330,`<rect x="40" y="40" width="240" height="240" fill="var(--soft)" stroke="var(--line)" stroke-width="2"/><text x="160" y="28" text-anchor="middle" font-size="18">espacio de diseño</text><text x="160" y="306" text-anchor="middle" font-size="16" class="m">x1</text><text x="16" y="165" font-size="16" class="m">x2</text><circle class="d" r="9" fill="var(--acc)"/>
<g class="r"><text x="470" y="28" text-anchor="middle" font-size="18">espacio de soluciones</text><line x1="470" y1="40" x2="470" y2="280" stroke="var(--ink)" stroke-width="3"/><text x="490" y="50" font-size="15" style="fill:var(--mut)">f alto</text><text x="490" y="280" font-size="15" style="fill:var(--mut)">f bajo</text><circle class="v" cx="470" r="9" fill="var(--blue)"/><path class="ar" fill="none" stroke="var(--mut)" stroke-width="2" stroke-dasharray="5 6"/><text class="fv" x="300" y="318" font-size="18" class="m"></text></g>
<g class="b3"><rect x="300" y="250" width="320" height="0"/></g>`);const q=c=>s.querySelector(c);return{tick(t,dt,P){const x1=Math.sin(t*.7)*.9,x2=Math.sin(t*1.1+1)*.9,X=160+x1*110,Y=160-x2*110,f=(x1*x1+x2*x2)/1.62,vy=280-f*240;at(q('.d'),{cx:X,cy:Y});at(q('.v'),{cy:vy});at(q('.ar'),{d:`M${X} ${Y} C ${X+120} ${Y}, 360 ${vy}, 460 ${vy}`});q('.fv').textContent=`f(x1, x2) = x1² + x2² = ${fmt(x1*x1+x2*x2,2)}`;op(q('.r'),P(2))}}};
V.catenary=root=>{const s=mount(root,640,330),a0=180,cy=(x,a)=>70+a*(Math.cosh(220/a)-Math.cosh((x-320)/a));
s.innerHTML=`<circle cx="100" cy="70" r="9" fill="var(--ink)"/><circle cx="540" cy="70" r="9" fill="var(--ink)"/><text x="80" y="54" font-size="20">A</text><text x="548" y="54" font-size="20">B</text><polyline class="rope" fill="none" stroke="var(--acc)" stroke-width="6" stroke-linecap="round"/><text class="t2" x="320" y="290" text-anchor="middle" font-size="19" style="fill:var(--green)">catenaria: energía potencial mínima con longitud fija</text><text class="t3" x="320" y="320" text-anchor="middle" font-size="16" class="m">min Ep = ρg ∫ y √(1 + y′²) dx   con  ∫ √(1 + y′²) dx = L</text>`;
const q=c=>s.querySelector(c);return{tick(t,dt,P){const a=a0+(1-P(2))*25*Math.sin(t*1.3);let d='';for(let x=100;x<=540;x+=8)d+=`${x},${cy(x,a).toFixed(1)} `;q('.rope').setAttribute('points',d);op(q('.t2'),P(2));op(q('.t3'),P(3))}}};
V.types=listViz([['Objetivos','Único (M = 1) o multiobjetivo (M > 1): el motor eficiente, limpio y silencioso.'],['Restricciones','Sin restricciones, de igualdad o de desigualdad (φ = 0 equivale a φ ≤ 0 y φ ≥ 0).'],['Forma','Lineal (programación lineal), no lineal, cuadrática.'],['Paisaje','Unimodal (convexo) o multimodal.'],['Variables','Discretas (enteras, combinatoria: viajante, mochila), continuas o mixtas.'],['Determinismo','Determinista o estocástica / robusta (con ruido o incertidumbre).']]);
V.landscape=root=>{const f1=(x,y)=>x*x+y*y,f2=(x,y)=>Math.sin(x)*Math.sin(y),i1=heat(f1,-5,5,-5,5,80,80),i2=heat(f2,-5,5,-5,5,80,80),m2=Mp(-5,5,-5,5,340,600,40,300);let mins='';[-4.712,-1.571,1.571,4.712].forEach(x=>[-4.712,-1.571,1.571,4.712].forEach(y=>{if(Math.sin(x)*Math.sin(y)<-.9)mins+=`<circle cx="${m2.X(x)}" cy="${m2.Y(y)}" r="9" fill="none" stroke="#FFC94A" stroke-width="3"/>`}));
const s=mount(root,640,330,`<g class="a"><image href="${i1}" x="40" y="40" width="260" height="260" preserveAspectRatio="none"/><circle cx="170" cy="170" r="9" fill="none" stroke="#FFC94A" stroke-width="3"/><text x="170" y="28" text-anchor="middle" font-size="18" class="m">x² + y²</text></g><g class="b"><image href="${i2}" x="340" y="40" width="260" height="260" preserveAspectRatio="none"/><text x="470" y="28" text-anchor="middle" font-size="18" class="m">sen x · sen y</text></g><g class="c">${mins}<text x="470" y="322" text-anchor="middle" font-size="16" style="fill:var(--red)">varios mínimos locales</text></g><text x="170" y="322" text-anchor="middle" font-size="16" style="fill:var(--green)">un único mínimo (global)</text>`);
const q=c=>s.querySelector(c);return{tick(t,dt,P){op(q('.a'),P(1)?1:.3);op(q('.b'),.2+.8*P(2));op(q('.c'),P(3))}}};
const H1=x=>1.4*Math.sin(1.1*x)+Math.sin(2.7*x+1)+.12*x+2.6,H1p=x=>1.54*Math.cos(1.1*x)+2.7*Math.cos(2.7*x+1)+.12;
V.treasure=root=>{const m=Mp(0,10,0,6,40,600,30,290);let gx=0,gb=-1e9;for(let x=0;x<=10;x+=.005)if(H1(x)>gb){gb=H1(x);gx=x}
const s=mount(root,640,330,`<polyline points="${pts(H1,0,10,m,300)}" class="cv"/><path d="M${m.X(gx)} ${m.Y(gb)-46} l9 12 -9 12 -9 -12z" fill="#FFC94A" stroke="var(--ink)" stroke-width="2"/><text x="${m.X(gx)}" y="${m.Y(gb)-52}" text-anchor="middle" font-size="14" style="fill:var(--amber)">tesoro</text><g class="rnd"></g><circle class="hc" r="10" fill="var(--blue)"/><g class="rs"></g><g class="sw"></g><text class="lab" x="40" y="320" font-size="17" style="fill:var(--mut)"></text>`);
const q=c=>s.querySelector(c),add=(g,n,col)=>{for(let i=0;i<n;i++)q(g).insertAdjacentHTML('beforeend',`<circle r="7" fill="${col}"/>`);return[...q(g).children]};const rd=add('.rnd',8,'var(--mut)'),rs=add('.rs',5,'var(--acc)'),sw=add('.sw',7,'var(--teal)');
let rx=rd.map(()=>Math.random()*10),ra=0,hx=.4,rsx=[.4,2.5,4.6,6.4,8.6],swx=sw.map((_,i)=>.5+i*1.4);const climb=(x,dt)=>clamp(x+H1p(x)*dt*.9,0,10);
return{tick(t,dt,P,vs){ra+=dt;if(ra>.45&&P(1)>.5&&P(2)<.5){ra=0;rx=rx.map(()=>Math.random()*10)}rd.forEach((c,i)=>at(c,{cx:m.X(rx[i]),cy:m.Y(H1(rx[i]))-8}));op(q('.rnd'),P(1)*(1-P(2)));
if(SNAP){if(P(2)>=1)for(let i=0;i<300;i++)hx=climb(hx,.02);if(P(3)>=1)rsx=rsx.map(x=>{for(let i=0;i<300;i++)x=climb(x,.02);return x});}else{if(P(2)>.5)hx=climb(hx,dt);if(P(3)>.5)rsx=rsx.map(x=>climb(x,dt));if(P(4)>.5){const b=swx.reduce((a,x)=>H1(x)>H1(a)?x:a);swx=swx.map(x=>clamp(climb(x+(b-x)*dt*.5,dt*.6),0,10))}}
at(q('.hc'),{cx:m.X(hx),cy:m.Y(H1(hx))-10});op(q('.hc'),P(2));rs.forEach((c,i)=>at(c,{cx:m.X(rsx[i]),cy:m.Y(H1(rsx[i]))-8}));op(q('.rs'),P(3));sw.forEach((c,i)=>at(c,{cx:m.X(swx[i]),cy:m.Y(H1(swx[i]))-8}));op(q('.sw'),P(4));
q('.lab').textContent=['','búsqueda aleatoria','escalada de colinas: atascada en una cima local','escalada con reinicio aleatorio','búsqueda en grupo: enjambre'][clamp(vs>=99?0:vs,0,4)]||''}}};
V.algtree=listViz([['Determinísticos','Mismo punto de partida → misma trayectoria. Ej.: el simplex.'],['Con gradiente','Newton-Raphson: muy buenos en problemas suaves y unimodales.'],['Sin gradiente','Hooke-Jeeves y Nelder-Mead: solo usan valores de la función.'],['Estocásticos','Usan números aleatorios: cada ejecución es distinta.'],['Heurísticos','«Descubrir por prueba y error»: buenas soluciones, sin garantía.'],['Metaheurísticos','Aleatorización + búsqueda local. Población (AG, PSO) o trayectoria (SA).']]);
